// 雙向鏈結串列 + 直接定址表（key 範圍 0 ~ 10^4）
// 串列頭是最新、尾是最舊；get / put 皆為 O(1)
#define MAX_KEY 10001

typedef struct Node {
    int key, value;
    struct Node *prev, *next;
} Node;

typedef struct {
    int capacity, size;
    Node head, tail;                 // 哨兵節點
    Node* map[MAX_KEY];
} LRUCache;

static void detach(Node* n) {
    n->prev->next = n->next;
    n->next->prev = n->prev;
}

static void pushFront(LRUCache* c, Node* n) {
    n->next = c->head.next;
    n->prev = &c->head;
    c->head.next->prev = n;
    c->head.next = n;
}

LRUCache* lRUCacheCreate(int capacity) {
    LRUCache* c = calloc(1, sizeof(LRUCache));
    c->capacity = capacity;
    c->head.next = &c->tail;
    c->tail.prev = &c->head;
    return c;
}

int lRUCacheGet(LRUCache* obj, int key) {
    Node* n = obj->map[key];
    if (!n) return -1;
    detach(n);
    pushFront(obj, n);               // 移到最新
    return n->value;
}

void lRUCachePut(LRUCache* obj, int key, int value) {
    Node* n = obj->map[key];
    if (n) {
        n->value = value;
        detach(n);
        pushFront(obj, n);
        return;
    }
    if (obj->size == obj->capacity) {          // 淘汰最久沒用的
        Node* old = obj->tail.prev;
        detach(old);
        obj->map[old->key] = NULL;
        free(old);
        obj->size--;
    }
    n = malloc(sizeof(Node));
    n->key = key;
    n->value = value;
    pushFront(obj, n);
    obj->map[key] = n;
    obj->size++;
}

void lRUCacheFree(LRUCache* obj) {
    Node* n = obj->head.next;
    while (n != &obj->tail) {
        Node* next = n->next;
        free(n);
        n = next;
    }
    free(obj);
}
